function evaluate(formula) {
  const stack = [];
  for (const token of formula.split(" ")) {
    if ("+-*/".includes(token)) {
      const b = stack.pop();
      const a = stack.pop();
      stack.push(token === "+" ? a + b : token === "-" ? a - b : token === "*" ? a * b : a / b);
