class Stack {
  #items = [];
  push(item) {
    this.#items.push(item);
    return this;
  }
  pop() {
    if (this.#items.length === 0) throw new RangeError("empty stack");
    return this.#items.pop();
  }
  peek() {
    return this.#items.at(-1);
  }
}

