class RingBuffer {
  constructor(capacity) {
    this.slots = new Array(capacity);
    this.head = 0;
    this.size = 0;
  }
  enqueue(item) {
    if (this.size === this.slots.length) return false;
    this.slots[(this.head + this.size) % this.slots.length] = item;
    this.size++;
    return true;
  }
  dequeue() {
    const item = this.slots[this.head];
    this.slots[this.head] = undefined;
    this.head = (this.head + 1) % this.slots.length;
    this.size--;
    return item;
  }
}

const r = new RingBuffer(2);
console.log(r.enqueue("A"), r.enqueue("B"), r.enqueue("C"));
console.log(r.dequeue(), r.enqueue("C"), r.dequeue(), r.dequeue(), r.size);

