function runJobs(ids, handler, maxAttempts) {
  const queue = ids.map((id) => ({ id, attempts: 0 }));
  let head = 0;
  const done = [];
  const dead = [];
  while (head < queue.length) {
    const job = queue[head++];
    job.attempts++;
    try {
      handler(job.id, job.attempts);
      done.push(job.id);
    } catch {
      if (job.attempts < maxAttempts) queue.push(job);
      else dead.push(job.id);
    }
  }
  return { done, dead };
}

function send(id, attempt) {
  if (id === "PAY-2" && attempt < 2) throw new Error("timeout");
  if (id === "PAY-3") throw new Error("bounced");
}

const result = runJobs(["PAY-1", "PAY-2", "PAY-3", "PAY-4"], send, 3);
console.log("done:", result.done.join(" "), "| dead:", result.dead.join(" "));

