function viewProduct(recent, sku, limit) {
  const at = recent.indexOf(sku);
  if (at !== -1) recent.splice(at, 1);
  recent.unshift(sku);
  if (recent.length > limit) recent.pop();
}

const recent = [];
for (const sku of ["RICE", "OIL", "SALT", "RICE", "BEANS"]) viewProduct(recent, sku, 3);
